<template>
  <AppLoader v-if="isLoadingMetadata" subject="project dashboard" />
  <AppError v-else-if="metadataError" title="Failed to load project dashboard" :error="metadataError" />
  <AppEmpty v-else-if="!metadata" subject="project dashboard" />

  <section v-else-if="isCanvassing" class="flex flex-col gap-10">
    <PageTitle :subtitle="metadata.short_description">
      <template #title>
        <span class="flex flex-row items-center gap-2">
          {{ metadata.name }}
          <Badge class="text-base font-normal" :variant="getProjectStatus(metadata.status).variant">{{
            getProjectStatus(metadata.status).label
          }}</Badge>
        </span>
      </template>
    </PageTitle>
    <CanvassingProjectDashboard
      is-public
      tab="responses"
      :dashboard-hash="dashboardHash"
      :project-start-end-date="{ start: metadata.start_date, end: metadata.end_date }"
      :project-regions="metadata.regions"
    />
  </section>
</template>

<script setup lang="ts">
import { getProjectStatus } from '~/constants/projects';

definePageMeta({
  layout: 'share',
  auth: false,
  backGroup: 'share-project-dashboard',
});

const route = useRoute('share-project-dashboard-hash-responses');
const dashboardHash = computed(() => route.params.hash);

const {
  metadata,
  error: metadataError,
  isLoading: isLoadingMetadata,
  isCanvassing,
} = usePublicDashboardMetadata(dashboardHash);

// Tabs exist only on the canvassing dashboard — the legacy public dashboard lives at the root path.
watch(
  () => metadata.value,
  (resolved) => {
    if (resolved && !isCanvassing.value) {
      navigateTo({ name: 'share-project-dashboard-hash', params: { hash: dashboardHash.value } }, { replace: true });
    }
  },
  { immediate: true }
);

useHead({
  title: computed(() => `${metadata.value?.name ?? ''} Dashboard`),
});
</script>
